package com.example.kyrgyzkeyboard.data.local

import androidx.room.Dao
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query
import com.example.kyrgyzkeyboard.data.model.WordEntity

/**
 * 词库 DAO：全部查询使用 suspend 函数，调用方负责在 IO 调度器上运行。
 */
@Dao
interface DictionaryDao {

    /** 插入或替换词条。返回新的 rowId。 */
    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insert(word: WordEntity): Long

    /** 拉取全部词条，按频次降序、字典序升序。 */
    @Query("SELECT * FROM words ORDER BY frequency DESC, word ASC")
    suspend fun getAll(): List<WordEntity>

    /** 模糊搜索：匹配 word / pinyin / meaning。 */
    @Query(
        "SELECT * FROM words " +
            "WHERE word LIKE '%' || :query || '%' " +
            "   OR pinyin LIKE '%' || :query || '%' " +
            "   OR meaning LIKE '%' || :query || '%' " +
            "ORDER BY frequency DESC, word ASC"
    )
    suspend fun search(query: String): List<WordEntity>

    /** 按主键删除。 */
    @Query("DELETE FROM words WHERE id = :id")
    suspend fun delete(id: Long)

    /** 按主键将 frequency +1。 */
    @Query("UPDATE words SET frequency = frequency + 1 WHERE id = :id")
    suspend fun incrementFrequency(id: Long)

    /** 按词精确查询（自学习用）。*/
    @Query("SELECT * FROM words WHERE word = :word LIMIT 1")
    suspend fun findExact(word: String): WordEntity?
}